"""対象のファイルから、文章の断片を種類ごとに取り出す。

種類:
  md_skills   各プラグインの skills/**/*.md
  md_claude   CLAUDE.md
  md_other    そのほかの Markdown (README・CONCEPTS・agents・rules・tools の README など。docs/ と tmp/ は除く)
  py_comment  Python のコメント
  py_doc      Python の docstring
  py_str      Python の docstring 以外の文字列リテラル
  go_comment  Go のコメント
  go_str      Go の文字列リテラル
  sh_comment  シェルのコメント
  sh_other    シェルのコメント以外
  other       そのほか (JSON・TOML・YAML・stdout など)
"""
import ast
import io
import json
import subprocess
import sys
import tokenize

ROOT = "/Users/akima/workspace/claude-plugins"


def tracked():
    out = subprocess.run(["git", "-C", ROOT, "ls-files"], capture_output=True, text=True, check=True).stdout
    for p in out.splitlines():
        if p.startswith(("docs/", "tmp/", ".claude/worktrees/")):
            continue
        yield p


def md_kind(p):
    if p == "CLAUDE.md" or p.endswith("/CLAUDE.md"):
        return "md_claude"
    if "/skills/" in p:
        return "md_skills"
    return "md_other"


def py_segments(p, src):
    doc_lines = set()
    try:
        tree = ast.parse(src)
    except SyntaxError:
        tree = None
    if tree is not None:
        for node in ast.walk(tree):
            if isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                body = getattr(node, "body", [])
                if body and isinstance(body[0], ast.Expr) and isinstance(getattr(body[0], "value", None), ast.Constant) and isinstance(body[0].value.value, str):
                    doc_lines.add(body[0].lineno)
    toks = tokenize.generate_tokens(io.StringIO(src).readline)
    for t in toks:
        if t.type == tokenize.COMMENT:
            yield "py_comment", t.start[0], t.string
        elif t.type == tokenize.STRING or (hasattr(tokenize, "FSTRING_MIDDLE") and t.type == tokenize.FSTRING_MIDDLE):
            kind = "py_doc" if t.start[0] in doc_lines and t.type == tokenize.STRING else "py_str"
            for i, line in enumerate(t.string.split("\n")):
                yield kind, t.start[0] + i, line


def go_segments(p, src):
    i, n, line = 0, len(src), 1
    buf, kind, start = [], None, 1

    def flush():
        nonlocal buf
        text = "".join(buf)
        for k, l in enumerate(text.split("\n")):
            yield kind, start + k, l
        buf = []

    while i < n:
        c = src[i]
        if src.startswith("//", i):
            j = src.find("\n", i)
            j = n if j < 0 else j
            yield "go_comment", line, src[i:j]
            i = j
            continue
        if src.startswith("/*", i):
            j = src.find("*/", i + 2)
            j = n if j < 0 else j + 2
            text = src[i:j]
            for k, l in enumerate(text.split("\n")):
                yield "go_comment", line + k, l
            line += text.count("\n")
            i = j
            continue
        if c == '"':
            j = i + 1
            while j < n and src[j] != '"':
                j += 2 if src[j] == "\\" else 1
            yield "go_str", line, src[i:j + 1]
            i = j + 1
            continue
        if c == "`":
            j = src.find("`", i + 1)
            j = n if j < 0 else j
            text = src[i:j + 1]
            for k, l in enumerate(text.split("\n")):
                yield "go_str", line + k, l
            line += text.count("\n")
            i = j + 1
            continue
        if c == "'":
            j = i + 1
            while j < n and src[j] != "'":
                j += 2 if src[j] == "\\" else 1
            i = j + 1
            continue
        if c == "\n":
            line += 1
        i += 1


def sh_segments(p, src):
    for no, l in enumerate(src.split("\n"), 1):
        s = l.lstrip()
        if s.startswith("#"):
            yield "sh_comment", no, l
        elif " #" in l:
            a, b = l.split(" #", 1)
            yield "sh_other", no, a
            yield "sh_comment", no, "#" + b
        else:
            yield "sh_other", no, l


def is_python(p, src):
    return p.endswith(".py") or src.startswith("#!/usr/bin/env python")


def is_shell(p, src):
    return p.endswith(".sh") or src.startswith(("#!/bin/sh", "#!/bin/bash", "#!/usr/bin/env bash", "#!/usr/bin/env sh")) or p.endswith("Makefile")


def segments():
    for p in tracked():
        try:
            src = open(f"{ROOT}/{p}", encoding="utf-8").read()
        except (UnicodeDecodeError, IsADirectoryError, FileNotFoundError):
            continue
        if p.endswith(".md"):
            for no, l in enumerate(src.split("\n"), 1):
                yield md_kind(p), p, no, l
        elif is_python(p, src):
            for k, no, l in py_segments(p, src):
                yield k, p, no, l
        elif p.endswith(".go"):
            for k, no, l in go_segments(p, src):
                yield k, p, no, l
        elif is_shell(p, src):
            for k, no, l in sh_segments(p, src):
                yield k, p, no, l
        else:
            for no, l in enumerate(src.split("\n"), 1):
                yield "other", p, no, l


if __name__ == "__main__":
    for k, p, no, l in segments():
        if any("぀" <= ch <= "ヿ" or "一" <= ch <= "鿿" for ch in l):
            print(json.dumps([k, p, no, l], ensure_ascii=False))

