"""用語ファイルの避ける語 (#135・#87) の出現を、指定したパスの範囲で数える・一覧にする。

使い方:
  python3 termcount.py count <パス...>
  python3 termcount.py list <pattern> <パス...>
"""
import re, subprocess, sys, tomllib

def files(paths):
    out = subprocess.run(['git', 'ls-files', '--'] + paths, capture_output=True, text=True).stdout.split()
    return [f for f in out if not f.endswith('terms.toml')]

def terms():
    ts = tomllib.load(open('.claude/akm-claude-plugins/wording-guard/terms.toml', 'rb'))['terms']
    return [t for t in ts if t['verdict'] == 'avoid' and ('/135' in t['decided_in'] or t['pattern'] == '周回')]

def rx(t):
    p = t['pattern']
    return re.compile(p[1:-1] if p.startswith('/') and p.endswith('/') else re.escape(p))

def hits(t, fs):
    r = rx(t); exc = t.get('exceptions', [])
    for f in fs:
        try:
            lines = open(f, encoding='utf-8').read().split('\n')
        except Exception:
            continue
        for no, l in enumerate(lines, 1):
            for m in r.finditer(l):
                if any(e in l[max(0, m.start() - 12):m.end() + 12] for e in exc):
                    continue
                yield f, no, l, m

if __name__ == '__main__':
    cmd = sys.argv[1]
    if cmd == 'count':
        fs = files(sys.argv[2:]); tot = 0
        for t in terms():
            hs = list(hits(t, fs)); tot += len(hs)
            print(f"{len(hs)}\t{t['pattern']}\t{len({h[0] for h in hs})} files")
        print('total', tot)
    else:
        pat = sys.argv[2]; fs = files(sys.argv[3:])
        t = next(t for t in terms() if t['pattern'] == pat)
        for f, no, l, m in hits(t, fs):
            print(f"{f}:{no}: {l.strip()[:220]}")
